using System.Security.Cryptography;namespace AirlyClient;public sealed class AirlyDeviceIdentity{private readonly string _path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Airly","device-key.bin");public ECDsa GetOrCreateKey(){Directory.CreateDirectory(Path.GetDirectoryName(_path)!);if(File.Exists(_path)){try{var e=File.ReadAllBytes(_path);var p=ProtectedData.Unprotect(e,null,DataProtectionScope.CurrentUser);var k=ECDsa.Create();k.ImportPkcs8PrivateKey(p,out _);CryptographicOperations.ZeroMemory(p);return k;}catch{}}var k2=ECDsa.Create(ECCurve.NamedCurves.nistP256);var p2=k2.ExportPkcs8PrivateKey();File.WriteAllBytes(_path,ProtectedData.Protect(p2,null,DataProtectionScope.CurrentUser));CryptographicOperations.ZeroMemory(p2);return k2;}public static string PublicKey(ECDsa k)=>Convert.ToBase64String(k.ExportSubjectPublicKeyInfo());public static string Sign(ECDsa k,string c)=>Convert.ToBase64String(k.SignData(System.Text.Encoding.UTF8.GetBytes(c),HashAlgorithmName.SHA256));}